/**
 * Embeds the A2UI project's 43 example surfaces in the native catalog example.
 *
 * SwiftPM resources have to live inside the target, and `vendor/spec/` is never edited or
 * copied about — so the examples travel as a generated Swift file instead, committed so
 * the app opens and runs without a JavaScript toolchain, and regenerated by
 * `pnpm sync:native` alongside the renderer bundle. CI fails if the committed copy is
 * stale, as it does for the bundle.
 *
 * Each example becomes a `Showcase` whose `message` is the whole message stream as a JSON
 * array, in a raw string literal so nothing inside needs escaping.
 */
import { readdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const repoRoot = join(here, '..', '..')

const CORPORA = [
    { version: 'v1_0', group: 'spec', prefix: 'spec-', label: 'v1.0' },
    { version: 'v0_9', group: 'spec09', prefix: 'spec09-', label: 'v0.9' },
]

const defaultTarget = join(repoRoot, 'examples', 'ios', 'catalog', 'Sources', 'A2UICatalog', 'SpecExamples.generated.swift')
const target = resolve(process.argv[2] ?? defaultTarget)

const RAW_DELIMITER = '"""#'

function swiftString(text) {
    return JSON.stringify(text)
}

function entriesFor({ version, group, prefix }) {
    const source = join(repoRoot, 'vendor', 'spec', version, 'catalogs', 'basic', 'examples')

    const files = readdirSync(source)
        .filter((name) => name.endsWith('.json'))
        .sort((left, right) => left.localeCompare(right))

    return files.map((file) => {
        const example = JSON.parse(readFileSync(join(source, file), 'utf8'))
        const id = prefix + file.replace(/\.json$/, '')
        const messages = JSON.stringify(example.messages ?? [], null, 2)

        if (messages.includes(RAW_DELIMITER)) {
            throw new Error(`${file} contains the raw string delimiter`)
        }

        return `        Showcase(
            id: ${swiftString(id)},
            title: ${swiftString(example.name ?? file.replace(/\.json$/, ''))},
            summary: ${swiftString(example.description ?? '')},
            group: .${group},
            message: #"""
${messages}
"""#
        ),`
    })
}

const sections = CORPORA.map((corpus) => {
    const entries = entriesFor(corpus)

    return { ...corpus, entries }
})

const output = `// Generated by \`pnpm sync:native\` from vendor/spec/*/catalogs/basic/examples — do not edit.
//
// The example surfaces the A2UI project ships, as the message streams an agent would send.
// v1.0 is the corpus the conformance suite renders; v0.9 is what every upstream renderer,
// gallery and demo still shows, so it is the like-for-like comparison. Both render through
// the same catalog: the engine answers to either catalog id.

enum SpecExamples {

    /// The ${sections[0].entries.length} v1.0 examples.
    static let all: [Showcase] = v1

    static let v1: [Showcase] = [
${sections[0].entries.join('\n\n')}
    ]

    /// The ${sections[1].entries.length} v0.9 examples.
    static let v09: [Showcase] = [
${sections[1].entries.join('\n\n')}
    ]
}
`

writeFileSync(target, output)

console.log(
    `sync-spec-examples: ${sections.map((section) => `${section.entries.length} ${section.label}`).join(' + ')} examples → ${target}`
)
